1	/**
2	 * 世界参数反馈环 — 统一游戏内所有动态参数的反馈闭环
3	 *
4	 * █████████████████████████████████████████████████
5	 * █  核心理念：现实只决定开局方向，             █
6	 * █  之后这局世界就是一个封闭演化系统，          █
7	 * █  由玩家选择和随机性驱动。                   █
8	 * █  玩家行为改变世界参数，世界参数改变事件概率。 █
9	 * █████████████████████████████████████████████████
10	 *
11	 * ┌──────────────────────┐
12	 * │  seedWorldFromReality │ ← 开局拉取真实数据（非必须，离线可回退）
13	 * └──────────┬───────────┘
14	 *            ↓ 转化为初始参数
15	 * ┌──────────────────────┐
16	 * │    _worldParams       │ ← 统一状态管理
17	 * │  ├ sectorHeat         │    行业热度（玩家行为→反馈→事件）
18	 * │  ├ marketMood         │    市场情绪
19	 * │  ├ playerWealthLevel  │    玩家财富等级
20	 * │  ├ volatilityTrend    │    波动趋势
21	 * │  └ ...                │
22	 * └──────┬───────────────┘
23	 *        │ 每日管线 tickWorldParams
24	 *        ├ applyWealthFeedback    ← 玩家财富→世界
25	 *        ├ applySectorFeedback    ← 玩家行为→行业热度
26	 *        ├ applyMarketFeedback    ← 行业内部传导
27	 *        ├ decayWorldParams       ← 自然衰减回基线
28	 *        └ updateMarketMood       ← 重新计算情绪
29	 *        ↓
30	 * ┌───────────────────────────┐
31	 * │  反馈消费方（多方读取）       │
32	 * ├  investment.js → 股价趋势    │
33	 * ├  events.js    → 事件权重     │
34	 * ├  news.js      → 新闻概率     │
35	 * ├  npcs.js      → NPC对话     │
36	 * └  jobs.js      → 工作收入     │
37	 * └───────────────────────────┘
38	 */
39	
40	// ====== 行业列表（与 investment.js INV_STOCKS 对齐） ======
41	const WORLD_SECTORS = ["科技", "消费", "金融", "房地产", "医药", "新能源"];
42	
43	// ====== 默认世界参数（新游戏时生成） ======
44	function createDefaultWorldParams() {
45	  // 初始各行业热度均衡
46	  var sectors = {};
47	  for (var i = 0; i < WORLD_SECTORS.length; i++) {
48	    sectors[WORLD_SECTORS[i]] = 1.0;
49	  }
50	
51	  return {
52	    // --- 开局种子（开局一次，不再变动） ---
53	    seedDate: null, // 现实日期（离线时为 null）
54	    seedSource: "random", // 'random' | 'realtime'
55	    baseVolatility: 1.0, // 基础波动率（影响所有随机游走幅度）
56	    initialSectorBias: JSON.parse(JSON.stringify(sectors)), // 开局时的行业初始偏移
57	
58	    // --- 动态参数（每日更新） ---
59	    sectorHeat: JSON.parse(JSON.stringify(sectors)), // 当前行业热度（1.0 = 均衡）
60	    marketMood: "neutral", // 市场情绪: bullish / bearish / neutral / volatile
61	    volatilityTrend: 0, // 波动趋势方向 (-1~1, 累积后取 sign)
62	
63	    // --- 玩家反馈累积 ---
64	    playerWealthLevel: 0, // 0~5: 玩家财富等级
65	    playerFameLevel: 0, // 0~5: 玩家名气等级
66	    sectorPlayerActivity: {}, // { "科技": 3, ... } 玩家近期在行业的活跃天数
67	
68	    // --- 反馈衰减状态 ---
69	    lastUpdateDay: 0,
70	    decayRate: 0.02, // 每日向基线衰减 2%
71	  };
72	}
73	
74	// ====== 开局种子：从现实拉取参数 ======
75	
76	/**
77	 * 从现实世界获取当日市场情绪，seed 到游戏世界参数。
78	 * 纯前端实现，使用免费公开 API。
79	 * 网络失败则自动回退到随机参数。
80	 *
81	 * 设计原则：
82	 * - 网络不通时玩家完全无感（回退随机默认值）
83	 * - 只取「方向性」参数（涨/跌/震荡），不取具体新闻
84	 * - 不存储任何玩家数据到外部
85	 */
86	function seedWorldFromReality(state) {
87	  var params = state._worldParams || createDefaultWorldParams();
88	  params.seedDate = new Date().toISOString().slice(0, 10);
89	
90	  // 尝试拉取真实市场数据（使用 Yahoo Finance 免费查询接口）
91	  // 中国A股：000001.SS（上证指数）
92	  var fetchUrl =
93	    "https://query1.finance.yahoo.com/v8/finance/chart/000001.SS?range=5d&interval=1d";
94	
95	  // 由于是纯前端 fetch，用 try-catch 兜底
96	  var success = false;
97	
98	  try {
99	    // 使用 XMLHttpRequest 的同步风格（保持脚本加载顺序兼容性）
100	    var xhr = new XMLHttpRequest();
101	    xhr.open("GET", fetchUrl, false); // 同步请求（开局时阻塞可接受）
102	    xhr.timeout = 5000;
103	    xhr.send(null);
104	
105	    if (xhr.status === 200) {
106	      var data = JSON.parse(xhr.responseText);
107	      if (
108	        data &&
109	        data.chart &&
110	        data.chart.result &&
111	        data.chart.result.length > 0
112	      ) {
113	        var result = data.chart.result[0];
114	        var closes =
115	          result.indicators && result.indicators.quote
116	            ? result.indicators.quote[0].close
117	            : null;
118	
119	        if (closes && closes.length >= 2) {
120	          // 计算最近两个交易日的涨跌幅
121	          var prevClose = closes[closes.length - 2];
122	          var latestClose = closes[closes.length - 1];
123	          var changePercent = (latestClose - prevClose) / prevClose;
124	
125	          // 计算5日波动率（用最近5个close的标准差/均值）
126	          var n = Math.min(closes.length, 5);
127	          var sum = 0;
128	          for (var ci = closes.length - n; ci < closes.length; ci++) {
129	            sum += closes[ci];
130	          }
131	          var mean = sum / n;
132	          var variance = 0;
133	          for (var cj = closes.length - n; cj < closes.length; cj++) {
134	            variance += (closes[cj] - mean) * (closes[cj] - mean);
135	          }
136	          var stddev = Math.sqrt(variance / n);
137	          var cv = stddev / mean; // 变异系数（波动率指标）
138	
139	          // 设置市场情绪
140	          if (changePercent > 0.015) {
141	            params.marketMood = "bullish";
142	          } else if (changePercent < -0.015) {
143	            params.marketMood = "bearish";
144	          } else if (cv > 0.02) {
145	            params.marketMood = "volatile";
146	          } else {
147	            params.marketMood = "neutral";
148	          }
149	
150	          // 设置波动率
151	          params.baseVolatility = Math.max(0.5, Math.min(2.0, 1.0 + cv * 10));
152	
153	          // 设置行业初始偏移（基于市场情绪）
154	          for (var si = 0; si < WORLD_SECTORS.length; si++) {
155	            var sec = WORLD_SECTORS[si];
156	            switch (sec) {
157	              case "科技":
158	                params.initialSectorBias[sec] =
159	                  params.marketMood === "bullish" ? 1.1 : 0.95;
160	                break;
161	              case "消费":
162	                params.initialSectorBias[sec] = 1.0;
163	                break;
164	              case "金融":
165	                params.initialSectorBias[sec] =
166	                  params.marketMood === "bearish" ? 0.9 : 1.05;
167	                break;
168	              case "房地产":
169	                // 房地产波动范围更宽（0.70-1.30），反映真实市场大起大落
170	                switch (params.marketMood) {
171	                  case "bullish":
172	                    params.initialSectorBias[sec] = 1.0 + Math.random() * 0.3;
173	                    break;
174	                  case "bearish":
175	                    params.initialSectorBias[sec] = 0.7 + Math.random() * 0.2;
176	                    break;
177	                  default:
178	                    params.initialSectorBias[sec] = 0.8 + Math.random() * 0.4;
179	                }
180	                break;
181	              case "医药":
182	                params.initialSectorBias[sec] = 1.02;
183	                break;
184	              case "新能源":
185	                params.initialSectorBias[sec] = 1.08;
186	                break;
187	              default:
188	                params.initialSectorBias[sec] = 1.0;
189	            }
190	          }
191	
192	          // 将 initialSectorBias 复制到 sectorHeat
193	          for (var sk in params.initialSectorBias) {
194	            params.sectorHeat[sk] = params.initialSectorBias[sk];
195	          }
196	
197	          params.seedSource = "realtime";
198	          success = true;
199	
200	          StateManager.addMessage(
201	            "🌐 世界参数已根据今日市场数据初始化（" +
202	              params.marketMood +
203	              "，波动率" +
204	              params.baseVolatility.toFixed(2) +
205	              "）",
206	            "info",
207	          );
208	        }
209	      }
210	    }
211	  } catch (e) {
212	    // 网络失败：静默回退，不报错
213	  }
214	
215	  if (!success) {
216	    // ====== 离线/网络失败回退：随机种子 ======
217	    params.marketMood = ["bullish", "bearish", "neutral", "volatile"][
218	      Math.floor(Math.random() * 4)
219	    ];
220	    params.baseVolatility = 0.8 + Math.random() * 0.8;
221	
222	    for (var si2 = 0; si2 < WORLD_SECTORS.length; si2++) {
223	      var sec2 = WORLD_SECTORS[si2];
224	      // 房地产行业波动范围更宽（0.70-1.30），其余行业范围较窄（0.85-1.15）
225	      if (sec2 === "房地产") {
226	        params.initialSectorBias[sec2] = 0.7 + Math.random() * 0.6;
227	      } else {
228	        params.initialSectorBias[sec2] = 0.85 + Math.random() * 0.3;
229	      }
230	      params.sectorHeat[sec2] = params.initialSectorBias[sec2];
231	    }
232	
233	    params.seedSource = "random";
234	    params.seedDate = null;
235	
236	    StateManager.addMessage("🌐 世界参数已随机初始化（离线模式）", "info");
237	  }
238	
239	  state._worldParams = params;
240	  return params;
241	}
242	
243	// ====== 每日参数更新 ======
244	
245	/**
246	 * 每日世界参数更新（在 daily_pipeline 中调用）
247	 * 所有反馈逻辑汇聚于此，集中管理，避免各模块各自为政。
248	 */
249	function tickWorldParams(state) {
250	  var params = state._worldParams;
251	  if (!params) {
252	    params = createDefaultWorldParams();
253	    state._worldParams = params;
254	  }
255	  if (params.lastUpdateDay >= state.player.day) return;
256	  params.lastUpdateDay = state.player.day;
257	
258	  // 1. 玩家财富反馈
259	  applyWealthFeedback(state);
260	
261	  // 2. 玩家行为→行业热度
262	  applySectorFeedback(state);
263	
264	  // 3. 行业间的内部传导（行业A热→关联行业B变热）
265	  applyMarketFeedback(state);
266	
267	  // 4. 自然衰减（防止无限累积）
268	  decayWorldParams(state);
269	
270	  // 5. 重新计算市场情绪
271	  updateMarketMood(state);
272	}
273	
274	// ====== 反馈函数 ======
275	
276	/**
277	 * Loop 1: 玩家财富 → 世界参数
278	 *
279	 * 玩家的总资产（现金+银行存款）映射到 wealthLevel，
280	 * 这会影响 NPC 态度、银行利率、购房选项等。
281	 *
282	 * 财富等级：
283	 *   0 = 破产边缘（< ¥100）
284	 *   1 = 勉强糊口（¥100~¥1k）
285	 *   2 = 生活稳定（¥1k~¥10k）
286	 *   3 = 小有积蓄（¥10k~¥50k）
287	 *   4 = 富裕阶层（¥50k~¥200k）
288	 *   5 = 财务自由（¥200k+）
289	 */
290	function applyWealthFeedback(state) {
291	  var params = state._worldParams;
292	  var cash = state.resources.cash || 0;
293	  var bank = state.resources.bankBalance || 0;
294	  var totalAssets = cash + bank;
295	
296	  var newLevel;
297	  if (totalAssets >= 200000) newLevel = 5;
298	  else if (totalAssets >= 50000) newLevel = 4;
299	  else if (totalAssets >= 10000) newLevel = 3;
300	  else if (totalAssets >= 1000) newLevel = 2;
301	  else if (totalAssets >= 100) newLevel = 1;
302	  else newLevel = 0;
303	
304	  // 财富等级变化时触发消息
305	  if (newLevel !== params.playerWealthLevel) {
306	    var wealthMessages = [
307	      "💸 你几乎身无分文...", // 0
308	      "🪙 手头有点紧，但还活着", // 1
309	      "💰 财务状况还算稳定", // 2
310	      "💵 攒了些钱，心里踏实多了", // 3
311	      "🧧 你已经是不折不扣的有钱人了", // 4
312	      "👑 财务自由！这座城市对你来说已经没有什么买不起的了", // 5
313	    ];
314	    // 只在升级时提醒（降级不打扰）
315	    if (newLevel > params.playerWealthLevel) {
316	      StateManager.addMessage(
317	        wealthMessages[Math.min(newLevel, wealthMessages.length - 1)],
318	        "success",
319	      );
320	    }
321	    params.playerWealthLevel = newLevel;
322	  }
323	
324	  // 名气等级（从 player.fame 映射）
325	  var fame = state.player.fame || 0;
326	  var fameLevel;
327	  if (fame >= 80) fameLevel = 5;
328	  else if (fame >= 60) fameLevel = 4;
329	  else if (fame >= 40) fameLevel = 3;
330	  else if (fame >= 20) fameLevel = 2;
331	  else if (fame >= 5) fameLevel = 1;
332	  else fameLevel = 0;
333	  params.playerFameLevel = fameLevel;
334	}
335	
336	/**
337	 * Loop 2: 行业热度驱动
338	 *
339	 * ⚠️ 设计原则：普通玩家的个人行为不改变行业热度。
340	 *   一个上班族在哪工作、散户买哪只股票——这些微观行为
341	 *   在宏观层面没有任何可测量的影响。
342	 *
343	 * 行业热度的真正驱动力（按影响力排序）：
344	 *   1. 随机日漂移 —— 市场自然的每日噪声（主力驱动）
345	 *   2. 行业关联传导 —— 上游行业热 → 下游升温（applyMarketFeedback）
346	 *   3. 重大新闻/事件 —— news.js 中已有投资影响（news_investment_bridge）
347	 *   4. 高影响力玩家 —— 财富/名气 ≥ 4 级时产生微弱边际影响
348	 *   5. CEO公司 —— 创业系统中有市场份额的大公司才有关联
349	 *
350	 * 参考游戏设计：
351	 *   - Capitalism Lab：员工不影响市场，CEO决策改变行业格局
352	 *   - Democracy 4：影响力通过系统杠杆传递，个人不直接影响宏观
353	 *   - 大多数：世界是独立环境，玩家在其中适应而非改变
354	 */
355	function applySectorFeedback(state) {
356	  var params = state._worldParams;
357	  if (!params) return;
358	  var vol = params.baseVolatility || 1.0;
359	
360	  // ====== 1. 随机日漂移（主力行业波动来源） ======
361	  // 每个行业每日有微小随机波动，模拟市场自然噪声。
362	  // 漂移中心化偏正（0.4 偏移 → 约 60% 概率小幅上涨），
363	  // 模拟经济长期温和增长。漂移幅度受 baseVolatility 放大。
364	  // 日漂移范围约：-0.015 ~ +0.0225（vol=1.0时）
365	  // 年化约：-5.5% ~ +8.2% —— 和真实市场长期趋势一致
366	  for (var si = 0; si < WORLD_SECTORS.length; si++) {
367	    var sec = WORLD_SECTORS[si];
368	    var drift = (Math.random() - 0.4) * 0.025 * vol;
369	    params.sectorHeat[sec] = (params.sectorHeat[sec] || 1.0) + drift;
370	  }
371	
372	  // ====== 2. 高影响力玩家门槛效应 ======
373	  // 只有财富等级 ≥ 4（¥50k+）或名气等级 ≥ 4（名声显赫）时，
374	  // 玩家的存在才会对所在行业产生边际影响（≈普通日漂移的一半）。
375	  //
376	  // 设计意图：给高成就玩家「世界因我而动」的成就感，
377	  // 但影响力微弱到不会破坏平衡——一个行业要持续升温，
378	  // 仍需外部新闻/事件的配合。
379	  if (params.playerWealthLevel >= 4 || params.playerFameLevel >= 4) {
380	    var job = state.employment && state.employment.currentJob;
381	    if (job && typeof getJobSector === "function") {
382	      var sector = getJobSector(job);
383	      if (sector && WORLD_SECTORS.indexOf(sector) >= 0) {
384	        // 影响力仅相当于一次日漂移的 ~20%
385	        params.sectorHeat[sector] = (params.sectorHeat[sector] || 1.0) + 0.003;
386	      }
387	    }
388	  }
389	
390	  // ====== 3. CEO 公司影响（创业系统联动） ======
391	  // 玩家经营一家成功的公司 → 公司所处的行业获得微量加持。
392	  // 公司影响力取决于市场份额（市场占有率越高，行业影响力越大）。
393	  // 设计参考：Capitalism Lab 中巨头公司改变行业格局。
394	  if (
395	    state.enterprise &&
396	    state.enterprise.company &&
397	    state.enterprise.company.industry
398	  ) {
399	    var company = state.enterprise.company;
400	    var ceoEffect = 0;
401	
402	    if (company.marketShare && company.marketShare > 30) {
403	      ceoEffect = 0.005; // 行业巨头（30%+市场份额）
404	    } else if (company.marketShare && company.marketShare > 15) {
405	      ceoEffect = 0.003; // 行业领军（15%+）
406	    } else if (company.stage && company.stage >= 3) {
407	      ceoEffect = 0.002; // B轮+ 有影响力的新锐
408	    }
409	
410	    if (ceoEffect > 0 && WORLD_SECTORS.indexOf(company.industry) >= 0) {
411	      params.sectorHeat[company.industry] =
412	        (params.sectorHeat[company.industry] || 1.0) + ceoEffect;
413	    }
414	  }
415	  // ====== 明确移除的逻辑 ======
416	  // ❌ 普通职业影响（上班族不改变行业）
417	  // ❌ 散户持股影响（零售投资者不改变市场方向）
418	  // ❌ 小额交易影响（¥10k以下资金流无宏观影响力）
419	}
420	
421	/**
422	 * Loop 3: 行业间的内部传导
423	 *
424	 * 一个行业热度升高 → 关联行业也会被带动（如科技热→新能源热）。
425	 * 关联矩阵定义行业间的传导系数。
426	 */
427	function applyMarketFeedback(state) {
428	  var params = state._worldParams;
429	
430	  // 行业关联传导矩阵（source → targets + 系数）
431	  var conductionMatrix = {
432	    科技: { 新能源: 0.15, 消费: 0.05 },
433	    新能源: { 科技: 0.1, 消费: 0.05, 金融: 0.08 },
434	    金融: { 房地产: 0.2, 消费: 0.08 },
435	    房地产: { 金融: 0.15, 消费: 0.1 },
436	    医药: { 科技: 0.08 },
437	    消费: { 金融: 0.05, 科技: 0.03 },
438	  };
439	
440	  for (var src in conductionMatrix) {
441	    var srcHeat = params.sectorHeat[src] || 1.0;
442	    var excess = srcHeat - 1.0; // 偏离基线的幅度
443	    if (Math.abs(excess) < 0.03) continue; // 小幅度忽略
444	
445	    var targets = conductionMatrix[src];
446	    for (var tgt in targets) {
447	      var coeff = targets[tgt];
448	      params.sectorHeat[tgt] = (params.sectorHeat[tgt] || 1.0) + excess * coeff;
449	    }
450	  }
451	}
452	
453	/**
454	 * 自然衰减：所有参数向基线回归。
455	 *
456	 * 衰减率 decayRate=0.02 意味着每天向基线靠近 2%。
457	 * 约 35 天后 50% 偏移被消除，约 115 天后 90% 被消除。
458	 *
459	 * 机制意义：玩家停止参与某个行业后，该行业热度逐渐回落，
460	 * 但不会立刻清零——保留了「余热效应」。
461	 */
462	function decayWorldParams(state) {
463	  var params = state._worldParams;
464	
465	  for (var sector in params.sectorHeat) {
466	    var baseline = params.initialSectorBias[sector] || 1.0;
467	    var current = params.sectorHeat[sector];
468	    var diff = current - baseline;
469	    params.sectorHeat[sector] = current - diff * params.decayRate;
470	  }
471	
472	  // volatilityTrend 也衰减
473	  params.volatilityTrend *= 0.95;
474	}
475	
476	/**
477	 * 从各维度数据推导市场情绪。
478	 * 综合 sectorHeat 的总体方向 + 排名。
479	 */
480	function updateMarketMood(state) {
481	  var params = state._worldParams;
482	  var heats = [];
483	  for (var s in params.sectorHeat) {
484	    heats.push(params.sectorHeat[s]);
485	  }
486	  if (heats.length === 0) {
487	    params.marketMood = "neutral";
488	    return;
489	  }
490	
491	  var avg =
492	    heats.reduce(function (a, b) {
493	      return a + b;
494	    }, 0) / heats.length;
495	  var maxHeat = Math.max.apply(null, heats);
496	  var minHeat = Math.min.apply(null, heats);
497	  var spread = maxHeat - minHeat;
498	
499	  if (spread > 0.25) {
500	    params.marketMood = "volatile";
501	  } else if (avg > 1.05) {
502	    params.marketMood = "bullish";
503	  } else if (avg < 0.95) {
504	    params.marketMood = "bearish";
505	  } else {
506	    params.marketMood = "neutral";
507	  }
508	}
509	
510	// ====== 读取接口 ======
511	
512	/** 获取指定行业当前热度 */
513	function getSectorHeat(industry) {
514	  if (typeof StateManager === "undefined" || !StateManager.getState) return 1.0;
515	  var state = StateManager.getState();
516	  if (!state._worldParams || !state._worldParams.sectorHeat) return 1.0;
517	  return state._worldParams.sectorHeat[industry] || 1.0;
518	}
519	
520	/** 获取当前市场情绪 */
521	function getMarketMood() {
522	  if (typeof StateManager === "undefined" || !StateManager.getState)
523	    return "neutral";
524	  var state = StateManager.getState();
525	  return (state._worldParams && state._worldParams.marketMood) || "neutral";
526	}
527	
528	/** 获取基础波动率 */
529	function getBaseVolatility() {
530	  if (typeof StateManager === "undefined" || !StateManager.getState) return 1.0;
531	  var state = StateManager.getState();
532	  return (state._worldParams && state._worldParams.baseVolatility) || 1.0;
533	}
534	
535	/** 获取玩家财富等级 */
536	function getPlayerWealthLevel() {
537	  if (typeof StateManager === "undefined" || !StateManager.getState) return 0;
538	  var state = StateManager.getState();
539	  return (state._worldParams && state._worldParams.playerWealthLevel) || 0;
540	}
541	
542	/** 获取玩家名气等级 */
543	function getPlayerFameLevel() {
544	  if (typeof StateManager === "undefined" || !StateManager.getState) return 0;
545	  var state = StateManager.getState();
546	  return (state._worldParams && state._worldParams.playerFameLevel) || 0;
547	}
548	
549	/**
550	 * 获取当前世界参数的概要文本（用于百科/UI展示）。
551	 * 返回结构化对象，便于不同模块按需渲染。
552	 */
553	function getWorldParamSummary(state) {
554	  var params = state._worldParams;
555	  if (!params) return null;
556	
557	  var moodIcons = {
558	    bullish: "📈",
559	    bearish: "📉",
560	    volatile: "🎢",
561	    neutral: "➡️",
562	  };
563	
564	  var sectorLines = [];
565	  for (var s in params.sectorHeat) {
566	    var heat = params.sectorHeat[s];
567	    var arrow = heat > 1.05 ? "↑" : heat < 0.95 ? "↓" : "→";
568	    sectorLines.push(s + " " + arrow + " " + (heat * 100).toFixed(0) + "%");
569	  }
570	
571	  return {
572	    seedSource: params.seedSource,
573	    seedDate: params.seedDate,
574	    marketMood: params.marketMood,
575	    marketMoodIcon: moodIcons[params.marketMood] || "➡️",
576	    baseVolatility: params.baseVolatility.toFixed(2),
577	    playerWealthLevel: params.playerWealthLevel,
578	    playerFameLevel: params.playerFameLevel,
579	    sectors: sectorLines.join(" | "),
580	    rawSectorHeat: JSON.parse(JSON.stringify(params.sectorHeat)),
581	  };
582	}
583	
584	/**
585	 * 获取某个行业的新闻/事件权重修正系数。
586	 * 热度高于1.0 → 该行业相关事件更可能发生（权重放大）。
587	 * 被 news_event_bridge.js 和 events.js 消费。
588	 */
589	function getSectorEventWeightMod(industry) {
590	  var heat = getSectorHeat(industry);
591	  if (heat >= 1.2) return 1.5;
592	  if (heat >= 1.1) return 1.25;
593	  if (heat <= 0.8) return 0.6;
594	  if (heat <= 0.9) return 0.8;
595	  return 1.0;
596	}
597	
598	// ====== 百科自更新 ======
599	if (typeof window !== "undefined") {
600	  window.MECHANICS = window.MECHANICS || {};
601	  window.MECHANICS.world_params = {
602	    id: "world_params",
603	    name: "世界参数反馈环",
604	    icon: "🌍",
605	    brief:
606	      "玩家行为→行业热度→事件概率的完整反馈闭环，让每局游戏的世界都有独特的演化轨迹",
607	    version: "1.0.0",
608	    related: [
609	      "mechanics:news_system",
610	      "mechanics:investment",
611	      "mechanics:startup_system",
612	    ],
613	    sections: [
614	      {
615	        kind: "desc",
616	        text: "世界参数反馈环是本游戏的核心设计概念。玩家每一个选择——做什么工作、买什么股票、攒多少钱——都会通过反馈环影响世界的后续演化。同时，开局时会从现实世界（实时市场数据）采样初始参数，让每局游戏的「底色」不同。",
617	      },
618	      {
619	        kind: "subhead",
620	        text: "🔄 三大反馈环",
621	      },
622	      {
623	        kind: "list",
624	        items: [
625	          "财富反馈：玩家总资产决定财富等级 → NPC态度、银行利率、购房选项受此影响",
626	          "行业热度：每日随机漂移+行业传导+新闻事件驱动，普通玩家不直接影响行业",
627	          "高影响力门槛：财富/名气≥4级或身为CEO时，才产生微弱边际影响",
628	          "传导反馈：一个行业热度升高 → 通过关联矩阵传导到相关行业",
629	        ],
630	      },
631	      {
632	        kind: "subhead",
633	        text: "📊 参数衰减与平衡",
634	      },
635	      {
636	        kind: "desc",
637	        text: "为了防止反馈环无限累积，所有参数每天以 2% 速率向初始基线回归。这意味着玩家停止参与某个行业后 35 天，该行业 50% 的偏移被消除；115 天后 90% 被消除。既保留了「余热效应」，又防止了永久性失衡。",
638	      },
639	      {
640	        kind: "subhead",
641	        text: "🌐 现实种子",
642	      },
643	      {
644	        kind: "desc",
645	        text: "新游戏开局时，游戏会尝试从 Yahoo Finance 免费接口获取上证指数近5日走势。根据数据计算市场情绪（看涨/看跌/震荡/中性）和波动率，转化为初始行业热度偏移。网络不通则自动回退到随机种子。现实只决定开局方向，之后世界是封闭演化系统。",
646	      },
647	    ],
648	  };
649	}
