    level: "L1",
    type: "investment",
    effects: {
      investmentEffect: [
        { industry: "科技", mul: 0.8 },
        { industry: "新能源", mul: 0.85 },
        { symbols: ["COPPER", "ALUM"], mul: 0.75 },
