191	        var flagCheck = rule.flag;
192	        if (flagCheck && !state.flags[flagCheck]) return;
193	      } else {
194	        // 条件检查
195	        if (typeof rule.condition === "function" && !rule.condition(state))
196	          return;
197	        // flag检查（有则要求对应flag为true）
198	        if (rule.flag && !state.flags[rule.flag]) return;
199	      }
200	      if (!state.relationships[id.replace("_flag_alt", "")]) {
201	        state.relationships[id.replace("_flag_alt", "")] = {
202	          affinity: 0,
203	          met: true,
204	        };
205	      }
206	      state.relationships[id.replace("_flag_alt", "")].affinity = Math.min(
207	        100,
208	        Math.max(
209	          -100,
210	          state.relationships[id.replace("_flag_alt", "")].affinity +
211	            rule.change,
212	        ),
213	      );
