224	function rollDailyNpcEcho(state) {
225	  if (!state.relationships) return;
226	  // 每天20%概率触发一个NPC回响
227	  if (Math.random() > 0.2) return;
228	
229	  // 只选择已经认识的NPC
230	  var knownNpcs = [];
231	  for (var id in state.relationships) {
232	    var rel = state.relationships[id];
233	    if (rel && rel.met) knownNpcs.push({ id: id, affinity: rel.affinity || 0 });
234	  }
235	  if (knownNpcs.length === 0) return;
236	
237	  // 权重：好感度越高越容易触发（熟人更常互动）
238	  var totalWeight = knownNpcs.reduce(function (sum, n) {
239	    return sum + Math.max(1, n.affinity + 20);
240	  }, 0);
241	  var roll = Math.random() * totalWeight;
242	  var selected = knownNpcs[0];
243	  var cursor = 0;
244	  for (var i = 0; i < knownNpcs.length; i++) {
245	    cursor += Math.max(1, knownNpcs[i].affinity + 20);
246	    if (roll <= cursor) {
247	      selected = knownNpcs[i];
248	      break;
249	    }
250	  }
251	
252	  // 生成回响消息
253	  var echoes = getNpcDailyEchoes(selected.id, selected.affinity, state);
254	  if (echoes) {
255	    StateManager.addMessage("💬 " + echoes, "info");
256	  }
257	}
